    SELECT #{runId}

INSERT INTO drama_sync_display_run_item (run_id, task_domain, task_id)
VALUES (#{runId}, #{taskDomain}, #{taskId})

mapper.select:
SELECT *
FROM drama_sync_display_run
WHERE id = #{runId}
  AND provider_id = #{providerId}
  AND sync_domain = #{domain}
  AND EXISTS (
      SELECT 1
      FROM drama_sync_display_run_item item
      WHERE item.run_id = drama_sync_display_run.id
        AND item.task_domain = #{domain}
  )

SELECT r.*
FROM drama_sync_display_run r
WHERE r.provider_id = #{providerId}
  AND r.sync_domain = #{domain}
  AND EXISTS (
      SELECT 1
      FROM drama_sync_display_run_item item
      WHERE item.run_id = r.id
        AND item.task_domain = #{domain}
  )
ORDER BY r.requested_at DESC, r.id DESC

SELECT *
FROM drama_sync_display_run
WHERE parent_run_id = #{parentRunId}
  AND sync_domain = #{domain}
  AND task_type = #{taskType}
ORDER BY requested_at DESC, id DESC
LIMIT 1

SELECT run_id, task_domain, task_id
FROM drama_sync_display_run_item
WHERE run_id = #{runId}
  AND task_domain = #{domain}
ORDER BY task_id ASC
